-- October locked in and November planned, from the CEO's outline of 2026-10-30.
--
-- Creative Triage. Data only. Generated once from the numbers read that day;
-- the sources and what each leaves out are on every row. Numbers tied to a
-- metric_key stay live on the screen until the month is locked.
--
-- Also logs the CEO's six churned clients in the churn register ("Log Churned
-- Clients"; on 30 Oct: "the 6th loss is correct. Add it, and the rest of them we
-- need to count as churned as well"). A soft remove by the CEO or an admin undoes
-- any of them. ClickUp is not touched here: flipping
-- Client Status fires the lifecycle automations, so that stays his call.

BEGIN;

INSERT INTO public.cockpit_goal_plans(period_kind,period_from,period_to,title,mission,headline,status,working_days,created_by)
VALUES ('month','2026-11-01','2026-11-30','November 2026 plan',
  'Mahara Media to $100,000 a month.',
  'Collect $43,300, the number October set and did not reach: 10 deals from 223 leads on $3,345 of lead-gen spend, keep about $19,400.',
  'draft',public.cockpit_goal_working_days('2026-11-01','2026-11-30'),'claude on the CEO''s outline, 2026-10-30')
ON CONFLICT (period_from,period_to) DO NOTHING;

INSERT INTO public.cockpit_goal_targets(plan_id,group_key,metric_key,label,unit,direction,target,note,sort)
SELECT p.id,v.g,v.k,v.l,v.u,v.d,v.t,v.n,v.s
FROM public.cockpit_goal_plans p, (VALUES
  ('front_end','spendRetargeting','Hammer Them ad spend','usd','up',394,'October''s share of lead-gen spend: 12.6% ($188.23 on $1,497.90).',1000),
  ('front_end','spend','Lead gen ad spend','usd','up',3125,NULL,1001),
  ('front_end','uniqueLinkClicks','Unique link clicks','count','up',5342,NULL,1002),
  ('front_end','cpc','CPC','usd','down',0.59,'October, held: $1,498.01 over 2,559 link clicks.',1003),
  ('front_end','landingPageConversion','Landing page conversion','rate','up',0.039,NULL,1004),
  ('front_end','leads','Leads','count','up',208,'$3,125 at $15 a lead.',1005),
  ('front_end','cpl','CPL','usd','down',15,'The official gate. October read $26.75 on tagged leads, $15.28 on the 98 leads on your sheet, $10.93 on the dashboard''s 137.',1006),
  ('front_end','leadToBooked','L2B','rate','up',0.6,'Your sheet''s October: 60 intros from 98 leads (61%). The tag rate (82.1%) likely reads high: setters tag by hand and 83 contacts have no tag. $15 at 60% is $25 an intro; October paid $24.56.',1007),
  ('front_end','introsBooked','Intro calls','count','up',125,'208 leads booking at 60%.',1008),
  ('front_end','costPerIntroBooked','Cost per intro','usd','down',25,NULL,1009),
  ('front_end','introsShown','Intros showed','count','up',63,'125 intros showing at 50%.',1010),
  ('front_end','introShowRate','Intro show rate','rate','up',0.5,'October 37.7% (23 of 61 due, B2B and the cockpit agree). Halfway to the 60% in October''s plan.',1011),
  ('front_end','costPerIntroShown','Cost per live intro','usd','down',50,NULL,1012),
  ('front_end','demosBooked','Demo calls','count','up',50,'52% of 63 intros held book a demo, plus 17 booked straight from a lead.',1013),
  ('front_end','costPerDemoBooked','Cost per demo','usd','down',63.13,NULL,1014),
  ('front_end','introToDemo','Intro to demo %','rate','up',0.52,'October: 12 of 23 held intros went on, 10 to a demo and 2 signed on the intro.',1015),
  ('front_end','directDemos','Direct demos','count','up',17,'October''s count held flat: 17 of the 29 leads who booked a demo had no held intro. Not in your outline; the plan needs it or it would ask for twice the leads.',1016),
  ('front_end','demosShown','Demos showed','count','up',32,'50 demos showing at 65%.',1017),
  ('front_end','demoShowRate','Demo show rate','rate','up',0.65,'October 53.3% (16 of 30 due). Halfway to the 75% in October''s plan.',1018),
  ('front_end','costPerDemoShown','Cost per live demo','usd','down',97.13,NULL,1019),
  ('front_end','offersMade','Offers made','count','up',29,NULL,1020),
  ('front_end','offerRate','Offer %','rate','up',0.9,'Every live demo in the 10 filed sales EODs got an offer (14 of 14). 90% allows for the unqualified ones. Your sheet''s 24 offers on 12 shown cannot be used.',1021),
  ('front_end','closes','Closed deals','count','up',10,'32 live demos closing at 30%.',1022),
  ('front_end','closeRate','Close rate %','rate','up',0.3,'October 31.3% (5 of 16 live demos), rounded down.',1023),
  ('front_end','newCash','Cash collected','usd','up',32434,'56% of $57,917 contracted, collected in the month.',1024),
