  ('money','labour','Labour expenses','usd','down',14615,'October''s team from your list less Nada: $7,750 (the new media buyer at his October $250). Ahmed Abushaiba at 15% of $32.4k new cash ($4,865) and $250 on 8 paid-in-full deals ($2,000). No bonus for you, the CSM, media or creative is priced.',1048),
  ('money','software','Software expenses','usd','down',5325,'The Costs page''s 44 active software lines, $5,324.74, usage lines at their estimate. The bank statement stops at 2 Oct, so it cannot check this month.',1049),
  ('money','profit','Total profit','usd','up',19841,'$43,300 in, $23,459 out.',1050),
  ('money','margin','Margin %','rate','up',0.458,NULL,1051),
  ('delivery','clientCpl','CPL','usd','down',15,'The official gate. October $13.24.',1055),
  ('delivery','clientCpb','CPB','usd','down',60,'$15 a lead over 25% lead to booking.',1056),
  ('calls','callLeadToBooking','Lead to booking','rate','up',0.25,'The official line: $15 at 25% is the $60 booking. October 15.9% (177 of 1,112); 3 of 19 clients reached it.',1057),
  ('back_end','clientsAtStart','Clients at start','count','up',18,'The daily roster''s paying clients on 30 Oct (28) less your five and the five on Ghosted: 15 active and 3 onboarding. October''s 21 is the same roster on 30 Sep.',2000),
  ('back_end','clientsChurned','Clients churned','count','down',1,'October''s plan said 10%; 10% of 18 is 1.8, so one is the line to beat. October lost 6 of 21 (28.6%).',2001),
  ('back_end','churnRate','Churn rate','rate','down',0.056,'One of 18. The register''s band: 5 to 8% is good.',2002),
  ('back_end','extensionsGiven','Client extensions given','count','down',2,'October: 3 named by you plus Marble''s on the billing sheet. Only Liwan''s and Marble''s are recorded; every one should be on the Extension form so the card shows it.',2003),
  ('back_end','upsells','Upsells','count','up',1,'October 0 closed. The add-on in Ocean Home''s proposal is the one to close.',2004),
  ('back_end','refunds','Refunds','count','down',0,'October $0. Marble''s $2,000 ask is open and would be the first.',2005),
  ('back_end','refundAmount','Refund amount','usd','down',0,'October $0; last 90 days $1,666.',2006),
  ('back_end','referrals','Referrals','count','up',1,'October''s plan, carried. No referral is recorded in October.',2007),
  ('back_end','testimonials','Testimonials','count','up',2,'October''s plan, carried.',2008),
  ('back_end','googleReviews','Reviews','count','up',2,'October''s plan, carried. The review and referral ask went live on 29 Oct.',2009),
  ('delivery','clientCpm','CPM','usd','down',12.46,'October, held: $11,028 over 885,329 impressions on the media buyer''s sync.',2010),
  ('delivery','clientLinkCtr','Link CTR','rate','up',0.0105,'October, held: 9,290 link clicks.',2011),
  ('delivery','clientOptIn','Opt in %','rate','up',0.094,'October, held: 876 leads over 9,290 clicks. These three make a $12.62 lead, under the gate.',2012),
  ('calls','callShowRate','Show rate %','rate','up',0.6,'The client line; the aim is 70%. October 38.6% (27 of 70 marked). Under it is a watch, never the constraint.',2013),
  ('calls','callLeadQuality','Avg lead quality','pts','up',6,'October 4.9 on 12 rated meetings. No gate exists, so this is a step up. The bigger ask is more ratings.',2014),
  ('calls','callCloseRate','Close rate %','rate','up',0.15,'October''s plan, carried. October 0 won of 27 shown, with 26 marked pending and 4 lost.',2015),
  ('creative','scriptsPerDay','Scripts per day','count','up',8,'October''s plan, and what the four ordinary EODs show: 33 scripts over 4 days (8.25).',2016),
  ('creative','newAngles','New angles tested','count','up',10,'October''s plan for new ads launched, carried. Nothing counted it in October.',2017),
  ('creative','videosPerDay','Videos per day','count','up',5,'October: 20 client videos on the 4 days an editor counted them (5 a day). October''s plan asked 8.',2018),
  ('creative','revisionsPerVideo','Revision per video','x','down',1,'No baseline: Frame.io versions are not recorded, so nothing measures it. One round is a starting line.',2019)
) AS v(g,k,l,u,d,t,n,s)
WHERE p.period_from='2026-11-01' AND p.period_to='2026-11-30'
  AND NOT EXISTS (SELECT 1 FROM public.cockpit_goal_targets x WHERE x.plan_id=p.id AND x.group_key=v.g AND x.metric_key=v.k);

