INSERT INTO public.cockpit_churn_departures(client,clickup_task_id,left_on,launched_on,reason,mrr_lost_usd,csm,note,source,created_by)
SELECT 'Marble and more','86eymcqdq','2026-10-19','2026-09-19','Cancelled',2000,'Rasem Abdel All','On the CEO''s list of 30 Oct. Dated by the client''s WhatsApp of 19 Oct: does not want to continue, wants the $2,000 back. Day 30 from launch.','cockpit','claude on the CEO''s outline, 2026-10-30'
