INSERT INTO public.cockpit_churn_departures(client,clickup_task_id,left_on,launched_on,reason,mrr_lost_usd,csm,note,source,created_by)
SELECT 'Joe and Sera Company','86ewvnqjb','2026-10-29','2026-04-28','Non-payment 14+ days',1666,'Rasem Abdel All','The CEO, 30 Oct: count it as churned. No payment on the rails since $1,666 fell due 24 Sep; dated the day he first wrote it. Launched 28 Apr, term ended 27 Jul, so the Churn page''s before-day-90 rule still files it as a finished term.','cockpit','claude on the CEO''s outline, 2026-10-30'
WHERE NOT EXISTS (SELECT 1 FROM public.cockpit_churn_departures d WHERE d.clickup_task_id='86ewvnqjb' AND d.removed_at IS NULL);
