INSERT INTO public.cockpit_goal_lockin_rows(month,section,sort,label,value,status,source,leaves_out,metric_key,client_task_id,answers,updated_by)
SELECT v.*, 'claude on the CEO''s outline, 2026-10-30' FROM (VALUES
  ('2026-10','churned',1,'Joe and Sera Company','Churned, $1,666 lost','partial','Your list of 30 Oct; ClickUp reads Active; billing sheet; their WhatsApp group. Launched 28 Apr, term ended 27 Jul.','You count it as churned, so this sheet does. The Churn page''s rule (before day 90) still files it as a finished term, so that page reads 5 and this reads 6.',NULL,'86ewvnqjb','{"form": "Not submitted: the form has no real response (3 ever, 2 from March and 1 internal test). You told the CSM to send it on 29 Oct; nothing confirms it went. Waits for your yes. Exit call first, then this link: https://maharamedia.typeform.com/to/knIe4eF3#onboarding_client_id=86ewvnqjb&client_name=Joe%20and%20Sera%20Company", "why": "Client in the WhatsApp group, 28 Sep: not 1 appointment in a month, asks for a timeline on a proper campaign. 8 Oct: will review and get back. Nothing since. No payment on the rails since $1,666 fell due 24 Sep. No held call since the one booked for 8 Sep. Maher asked to approve offboarding from 10 Oct and no answer is recorded.", "prevent": "Suggested: a client who says no appointments in a month gets a call and a dated plan that week. A missed payment gets a call inside a week, and the billing agent''s question gets an answer the same day."}'::jsonb),
  ('2026-10','churned',2,'Marble and more','Churned day 30, $2,000 lost','partial','Your list; ClickUp reads Active; client''s WhatsApp of 10 and 19 Oct; check-in calls of 30 Sep and 12 Oct.','Refund ask is open. The billing sheet also shows an extension to 2 Nov, given 19 Oct.',NULL,'86eymcqdq','{"form": "Not submitted: the form has no real response (3 ever, 2 from March and 1 internal test). You told the CSM to send it on 29 Oct; nothing confirms it went. Waits for your yes. Exit call first, then this link: https://maharamedia.typeform.com/to/knIe4eF3#onboarding_client_id=86eymcqdq&client_name=Marble%20and%20more", "why": "Client on WhatsApp. 10 Oct: two months with nothing real, wants the money back, last chance. 19 Oct: does not want to continue and demands the $2,000 back on the same card. Says nobody answers on WhatsApp, appointments do not show, the team is lost, and the agreement was a refund if no clients came. You told the assistant there is no refund clause. An AI recap of the 12 Oct call in the CSM''s EOD adds: leads reached after 1 to 2 days, the call centre did not know marble, generic videos, ad account blocked on payment.", "prevent": "Suggested: hold the promise made on 30 Sep (leads answered within 1 to 2 hours) before a new client''s second month, and brief the caller on the product before launch."}'::jsonb),
  ('2026-10','churned',3,'Atlantis Contracting','Churned day 49, $2,000 lost','partial','Your list; ClickUp reads Active; client''s message of 18 Oct; Fathom check-in 13 Oct; team Slack.','The team pushed back on 18 Oct and kept working: videos on 22 Oct, still operating on 27 Oct.',NULL,'86eyjkdc8','{"form": "Not submitted: the form has no real response (3 ever, 2 from March and 1 internal test). You told the CSM to send it on 29 Oct; nothing confirms it went. Waits for your yes. Exit call first, then this link: https://maharamedia.typeform.com/to/knIe4eF3#onboarding_client_id=86eyjkdc8&client_name=Atlantis%20Contracting", "why": "Client, 18 Oct: stop the ads and hold the process for an internal restructure, 50 days without results. 13 Oct call: wants closed deals, not leads, and says trust is the main problem. No payment on the rails for the $3,000 due 12 Oct, under the offer that they pay when they close a deal.", "prevent": "Suggested: no pay-on-close offer without a dated backstop. It left $3,000 waiting on the client''s own sales, which is where they said the problem was."}'::jsonb),
